extends RefCounted


static func get_version_string() -> String:
	return String(ProjectSettings.get_setting("application/config/version", "1.0.0"))


static func parse_semantic_version(version_str: String) -> Dictionary:
	var parts: PackedStringArray = version_str.strip_edges().split(".")
	if parts.size() != 3:
		return {}

	for part in parts:
		if not part.is_valid_int():
			return {}
		if part.to_int() < 0:
			return {}

	return {
		"major": parts[0].to_int(),
		"minor": parts[1].to_int(),
		"patch": parts[2].to_int()
	}


static func is_valid_semver(version_str: String) -> bool:
	var parsed := parse_semantic_version(version_str)
	return not parsed.is_empty()
